{{Knowledge|id=RENSTRA-ISS-1.13|type=Strategic Performance Indicator|domain=Digital Criminal Justice|jurisdiction=Indonesia|source=Renstra Mahkamah Agung 2025–2029|evidence=E3 — Official Primary Source|ai_readiness=5|status=VERIFIED}}

